import json
from pathlib import Path
P=Path(__file__).resolve().parents[1]/'out/raw-quota-backtest'
d=json.loads((P/'data.json').read_text());fit=json.loads((P/'fit.json').read_text());groups=json.loads((P/'subgroup-sensitivity.json').read_text())
labels={'free':'不计 auto-review','sol':'按 Sol 实际价','parent':'按父模型实际价'}
lines=['# 从原始日志排除旧额度快照影响后的回测','','## 结论','','可以减弱已识别的来源污染，并得到条件相容解；不能声称完全消除了所有结算时序误差。保留全部 11 个周期仍不相容。移除此前两个明显不相容的 Plus 周期，保留全部 5 Pro 和另外 4 Plus，并要求两个任务确认同一水位后，免费 auto-review 假设存在 ±1 点可行解。','','本次没有用挂件数据库里的用量与额度值。旧 data.json 仅提供固定比较起止时间、套餐标签及生图截止时间；token、fast 证据和百分比均重新从当前原始 rollout/HTTP 日志解析。原始日志与生产数据库未写入。','','## 新发现：子任务所有者归属错误','','子任务文件可以先包含自己的 session_meta，再包含复制进来的父任务 session_meta。旧解析器遇到后者时会覆盖 sessionId，从而把子任务后续记录归到父任务。独立回测解析器现在固定首个 session_meta 为文件所有者，忽略后续继承元数据，并排除子任务创建之前复制的 token_count 历史。父任务模型时间线也按文件所有者重建。新增回归测试覆盖这一情形。','','例如 01a094ff-578c… 子任务文件第 1 行是子任务元数据，第 2 行是父任务 01a094fc-a31c… 的元数据；09-12 17:50:03.747 的 8% 就记录在这个子任务文件里。此前按父任务文件名查找未找到，不能据此推断该观测不在原始日志中。旧报告的“同任务回退”归类和原始来源缺失判断需据此修正。该修复目前仅用于本次独立分析，未修改挂件生产解析器。','','## 固定清洗规则','','1. 按套餐、周期及生图前区间分组；只用解析器标为有效的主池观测。','2. 同一来源、同一任务只保留首次出现或本任务水位上升的记录，剔除重复附带的旧值。没有上升不代表一定陈旧，这一步是降低重复权重，不是逐条证明数据错误。','3. 只保留跨来源时间线的新高水位，避免用回退快照覆盖已见的较新水位。','4. 更严格的确认集：首次新高后 120 秒内，另一个任务也首次报告同一水位，且确认前没有更高水位。','5. 测量时刻按“首次报告到第二任务确认”的区间处理，不把任一写入时间假装成精确结算时刻。这个区间仍是假设的近似，两个任务有可能共同携带旧值。另加前后 30/60/120/300 秒做敏感性检验，非测得的延迟。','','所有清洗规则均不依赖某组费率拟合得好不好，也没有删除某模型费率下残差最大的单条观测。两个被剔除的 Plus 周期是此前已识别的 08-21 02:00—08-24 04:08、08-24 08:53—08-25 03:44，因此整体仍是探索性、事后筛选分析，需要独立实验验证。','','## 样本保留','','| 观测口径 | 数量 |','|---|---:|']
for kind,label in [('raw','原始有效观测'),('fresh','各任务首次/上升水位'),('crossing','全局首次新高'),('confirmed','两个任务确认')]:
 r=next(r for r in fit['results'] if r['kind']==kind);lines.append(f"|{label}|{r['n']}|")
lines+=['','全 11 周期的确认集：260 条；剔除上述两个 Plus 后：228 条，9 个周期；只看全部 5 个 Pro：156 条。所有周期均仍有确认样本，没有暗中丢掉某个 Pro 周期。','','## 主要结果：9 周期、228 条确认观测','','Q 固定为 Plus=$100、Pro5×=$500，未标明 fast=1、fast=2.5；保留本地标准输入/缓存/输出比例，模型倍率共同拟合。每周期首点之前的用量是独立非负未知值；未通过确认筛选的原首点，不再被当作精确基线。','','RMSE 为另一个点估计最小二乘目标，允许每周期初始用量一起拟合，不能与此前固定首点差分的 RMSE 直接比较。可行性列由独立线性规划得到。','','| auto-review | 点估计 RMSE | 最小观测容差 | ±1 点可行 | 额外前后 60 秒时最小容差 |','|---|---:|---:|---|---:|']
for mode in labels:
 r=next(r for r in groups if r['group']=='drop2' and r['mode']==mode and r['lag']==0);q=next(r for r in groups if r['group']=='drop2' and r['mode']==mode and r['lag']==60)
 lines.append(f"|{labels[mode]}|{r['pointRMSE']:.3f}|±{r['halfWidth']:.3f}|{'是' if r['feasible']['1'] else '否'}|±{q['halfWidth']:.3f}|")
w=next(r for r in groups if r['group']=='drop2' and r['mode']=='free' and r['lag']==0)
lines+=['','## 一个实际可行的价格见证','','下面是优化最坏区间偏差得到的一组参数，不是点估计 RMSE 最低的参数，也不是唯一真实费率。','','| 模型 | 标准价格倍率 |','|---|---:|']
for m,v in w['intervalMultipliers'].items():lines.append(f'|{m}|{v:.6f}×|')
scale=w['capacityScaleAt1'];lines+=['',f"固定上述费率和该解各周期初始美元用量，并采用 ±1 点包络，所有观测的共同容量比例区间为 [{scale['lower']:.9f}, {scale['upper']:.9f}]。保持 Pro:Plus=5:1：",'',f"- Plus：${100*scale['lower']:.4f}—${100*scale['upper']:.4f}",f"- Pro5×：${500*scale['lower']:.4f}—${500*scale['upper']:.4f}",'','这个交集包含 $100/$500，是一组条件可行性的数值见证。它不是容量置信区间：价格、初始用量和周期都经过拟合/选择，换另一组可行价格区间会变。该见证仍不满足严格四舍五入 ±0.5 点。','','## 全部周期与时间敏感性','','保留全部 11 周期时，确认集所需最小容差分别约 ±2.895、±2.670、±2.670 点；即使再允许前后 300 秒，仍约 ±1.846、±1.681、±1.681 点。清洗没有把所有历史矛盾消掉。','','只看 5 个 Pro，确认集所需容差分别约 ±0.718、±0.879、±1.089 点；前后额外 60 秒后约 ±0.431、±0.624、±0.867 点。','','前后 300 秒时，9 周期三种方案都能通过 ±0.5 点检验，但时间范围越宽约束越弱，不能反过来说实际延迟就是五分钟。免费方案在较窄时序假设下已相容，是候选支持，不足以确认 auto-review 免费。','','## 复现','','`node scripts/backtest-raw-quota.cjs` 重扫原始日志；`python scripts/backtest-raw-quota.py` 比较清洗口径；subgroup-sensitivity.json 保存指定子集的时序检验。独立解析器是 scripts/raw-quota-source.cjs。固定数据输出供复核，新增日志不会改变已保存的快照。']
(P/'report.md').write_text('\n'.join(lines),encoding='utf-8')
print(P/'report.md')
